python3 - <<'PY'
strings=[]
for l in open('deploy.log'):
    s=l.rstrip('\n')
    if s.startswith('#') or s.startswith('ERROR'):
        strings.append(s)
print(strings)
from functools import lru_cache
n=len(strings)
def overlap(a,b):
    # max k < min(len(a),len(b)) such that a[-k:]==b[:k]
    for k in range(min(len(a),len(b)),0,-1):
        if a[-k:]==b[:k]:
            return k
    return 0
ov=[[overlap(strings[i],strings[j]) for j in range(n)] for i in range(n)]
for row in ov: print(row)
@lru_cache(None)
def dp(mask,last):
    if mask==(1<<n)-1:
        return 0
    best=10**9
    for j in range(n):
        if not mask>>j &1:
            add=len(strings[j])-ov[last][j] if last!=-1 else len(strings[j])
            best=min(best, add+dp(mask|1<<j,j))
    return best
print('shortest',dp(0,-1))
# reconstruct
def rec(mask,last):
    if mask==(1<<n)-1: return []
    for j in range(n):
        if not mask>>j &1:
            add=len(strings[j])-ov[last][j] if last!=-1 else len(strings[j])
            if dp(mask,last)==add+dp(mask|1<<j,j):
                return [j]+rec(mask|1<<j,j)
order=rec(0,-1)
s=''
last=-1
for j in order:
    if last==-1: s+=strings[j]
    else:
        k=ov[last][j]; s+=strings[j][k:]
    last=j
print(order,s,len(s))
for x in strings:
    print(x in s)
open('/tmp/super','w').write(s+'\n')
